const SL=k=>S(k).split(",");
const K="vyronSmart",ld=()=>{try{return JSON.parse(localStorage.getItem(K))||{}}catch{return{}}},sv=s=>{try{localStorage.setItem(K,JSON.stringify(s));return true}catch{try{toast(S("quota"))}catch{}return false}};
