/* ---------- RecoveryIntelligence (self-reported estimate only) + WorkoutFeedback ---------- */
function recovery(s,wk){const t=iso(new Date()),ci=s.ci&&s.ci.date===t?s.ci:null,f=(s.fb||[]).slice(-1)[0],rc=f&&Date.now()-f.t<2*864e5?f:null;if(!ci&&!rc)return null;let sc=90;if(ci)sc-=(ci.f-1)*12;if(rc){if(rc.diff>=4)sc-=10;sc-=rc.disc==="unusual"?25:rc.disc==="sore"?8:0}const dd=new Set(wk.map(x=>x.date)),y=new Date();y.setDate(y.getDate()-1);const y2=new Date(y);y2.setDate(y2.getDate()-1);if(dd.has(iso(y))&&dd.has(iso(y2)))sc-=10;sc=cl(sc,0,100);return{score:sc,st:sc>=65?"keep":sc>=40?"modify":"recover"}}
function applyFB(s,f){s.fb=[...(s.fb||[]),f].slice(-30);let w=s.w||0;const l2=s.fb.slice(-2),easy=x=>x.diff<=2&&x.comp==="yes"&&x.disc!=="unusual";if(f.diff>=4||f.disc==="unusual"||f.comp==="part")w--;else if(easy(f)&&l2.length===2&&l2.every(easy))w++;s.w=cl(w,-2,1)}
function todaySess(p,s,wk){const ds=weekDays(p,s,wk),day=ds.find(x=>x.today),rec=recovery(s,wk),rm=muscleRecovery(wkx(wk,s)),fat=rm.fatigued,mods=day&&s.qm&&s.qm.date===day.date?s.qm:{},r={ds,day,rec,rm,fat,mods,sess:null};if(!day||day.done)return r;
 const fin=(x,focus,mode)=>({...r,sess:applyModifiers(x,mods,p,assess(p).level,fat).sess,focus,mode});
 if(day.kind==="rec")return fin(gen(p,s,"rec",day.date,false),"rec","rec");if(day.kind!=="train")return r;
 if(rec&&rec.st==="recover"&&s.ovr!==day.date)return fin(gen(p,s,"rec",day.date,false),"rec","replaced");
 const ez=!!rec&&rec.st==="modify";return fin(gen(p,s,day.focus,day.date,ez,fat),day.focus,ez?"eased":"keep")}
async function syncSchedule(p,s){const cur=await all("schedule");for(const x of cur.filter(x=>x.smart))await remove("schedule",x.id);const wk=await all("workouts");for(const d of weekDays(p,s,wk).filter(d=>d.kind==="train"))await put("schedule",{id:uid(),day:DAYS_AR[d.i],name:S("f_"+d.focus),smart:true})}
