const autosave=()=>{if(!OB||OB.edit)return;const s=ld();s.draft={step:OB.step,d:OB.d};sv(s)};
function obRender(){const {d,step,edit}=OB,ov=document.getElementById("scOnb");ov.dir=getLang()==="ar"?"rtl":"ltr";
 ov.innerHTML=`<div class="sc-ob" role="dialog" aria-modal="true" aria-label="SMART COACH"><div class="sc-top"><b>SMART COACH</b><button class="sc-lnk" data-oa="${edit?"close":"later"}">${edit?"✕":S("later")}</button></div><div class="sc-pr" role="progressbar" aria-valuemin="1" aria-valuemax="5" aria-valuenow="${step}">${[1,2,3,4,5].map(i=>`<i class="${i<=step?"on":""}"></i>`).join("")}</div><p class="sc-m">${step}/5 · ${S("s"+step)}</p><div class="sc-bodyx" key="${step}">${stepHTML(step,d)}</div><p class="sc-err" id="scErr" role="alert"></p><div class="sc-row">${step>1?`<button class="secondary-btn" data-oa="prev">${S("back")}</button>`:""}${step===5?`<button class="secondary-btn" data-oa="next" data-skip="1">${S("skip")}</button>`:""}<button class="primary-btn" data-oa="next">${step===5?(edit?S("save"):S("fin")):S("next")}</button></div></div>`}
