const achCard=s=>{const a=(s.ach||[]).slice(-4).reverse();return`<section class="sc-card"><h2>${S("achH")}</h2>${a.length?`<ul class="sc-ul">${a.map(x=>`<li><b>${x.type.startsWith("pr")?"🏆":"🔥"} ${E(achText(x))}</b><span dir="ltr">${x.date}</span></li>`).join("")}</ul>`:`<p class="sc-m">${S("achNone")}</p>`}<p class="sc-m">${S("achSafe")}</p></section>`};
